 * // 일반 똥 2개 + 금똥/다이아똥 8개 생성
 * // 낙하 속도 1.2배 빠름
 */
export const FEVER_TIME_CONFIG: FeverTimeConfig = {
  firstTriggerScore: 250,
  baseInterval: 1200,
  intervalIncrement: 100,
  intervalIncreaseEvery: 3,
  duration: 4500,
  normalPoopCount: 2,
  bonusPoopCount: 8,
  speedMultiplier: 1.2, // 피버 타임 중 1.2배 빠른 속도
