import { getCurrentUserId } from './auth';
import { supabase } from './supabase';

export interface LeaderboardEntry {
  userId: string;
  userName: string;
  score: number;
  rank: number;
  characterType?: string;
}

export interface SubmitScoreResponse {
  success: boolean;
  isNewRecord: boolean;
  previousScore: number | null;
  newScore: number;
  rank: number | null;
  message?: string;
}

